mapper.select:
SELECT DISTINCT A.STRATEGY_ID id, A.STRATEGY_NAME text FROM PTL_INV_STRATEGY A WHERE 1=1
AND A.STRATEGY_ID = #{initValue}
AND (A.STRATEGY_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) or A.STRATEGY_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND A.STRATEGY_CLASS = #{strategyClass}

SELECT inv.USE_STATUS useStatus, inv.STRATEGY_ID strategyId, inv.STRATEGY_NAME strategyName, to_char(wm_concat(DISTINCT detClass.TYPE_2)) type2, detClass.BATCH_ID batchId, det.RATIO*100 ratio FROM PTL_INV_STRATEGY inv LEFT JOIN PTL_INV_STRATEGY_DETAIL det ON inv.STRATEGY_ID = det.STRATEGY_ID LEFT JOIN PTL_INV_STRATEGY_DETAIL_CLASS detClass ON det.BATCH_ID = detClass.BATCH_ID
AND (inv.STRATEGY_ID in
null) or inv.STRATEGY_ID in (
#{item}
)
AND detClass.TYPE_2 in
#{item}
AND inv.USE_STATUS in
#{item}
AND inv.STRATEGY_CLASS = #{strategyClass}
GROUP BY inv.USE_STATUS , inv.STRATEGY_ID , inv.STRATEGY_NAME , det.RATIO , detClass.BATCH_ID ORDER BY inv.STRATEGY_ID, det.RATIO

SELECT BATCH_ID batchId
FROM PTL_INV_STRATEGY_DETAIL 
WHERE STRATEGY_ID = #{strategyId, jdbcType=VARCHAR}
